// 2 Earnings: Antwort von Claude prüfen (v1.3)
// Holt das JSON aus der Werkzeug-Antwort, normalisiert es und setzt Prüfhinweise.
// Werte aus einer Abbildung lassen sich nicht wörtlich im Text gegenprüfen -> immer Hinweis "mit Abbildung vergleichen".

const PRICE_IN = 0.10 / 1e6, PRICE_OUT = 0.50 / 1e6, PRICE_CACHE_WRITE = 0.125 / 1e6, PRICE_CACHE_READ = 0.01 / 1e6;
const sources = $('2 Earnings: Prompt bauen').all();
const PFAD = {
  kategorie: '2 Earnings', ziel: '<TICKER>/2 Earnings', template: 'Analysten-Earnings',
  heute: 'Claude liest Grafik + Text und füllt das Earnings-Template',
  spaeter: ['Wertpapier-Übersicht <TICKER> aktualisieren'],
};

return $input.all().map((item, i) => {
  const res = item.json;
  const src = sources[i] ? sources[i].json : {};
  const { request, ...meta } = src;
  const errors = [];
  const warnings = [...(meta.warnings || [])];

  const tu = (res.content || []).find(c => c.type === 'tool_use');
  let e = tu ? JSON.parse(JSON.stringify(tu.input)) : null;
  if (!e || typeof e !== 'object') { errors.push('Keine strukturierte Earnings-Antwort von Claude erhalten' + (res.error ? `: ${JSON.stringify(res.error).slice(0, 200)}` : '')); e = {}; }

  const str = v => (v == null ? '' : String(v)).replace(/<\/?[a-z_]+(\s[^>]*)?>/gi, '').replace(/\|/g, '/').trim();
  const arr = v => Array.isArray(v) ? v : (v == null || v === '' ? [] : (typeof v === 'string' && v.trim().startsWith('[') ? (() => { try { return JSON.parse(v); } catch (x) { return [v]; } })() : [v]));
  const obj = v => (typeof v === 'string' ? (() => { try { return JSON.parse(v); } catch (x) { return {}; } })() : (v || {}));
  const kopf = v => { const o = obj(v); return { ist: str(o.ist), erwartung: str(o.erwartung), abweichung: str(o.abweichung), ergebnis: ['beat', 'inline', 'miss'].includes(String(o.ergebnis || '').toLowerCase()) ? String(o.ergebnis).toLowerCase() : '' }; };
  const zeilen = v => arr(v).map(obj).map(z => ({ kennzahl: str(z.kennzahl), wert: str(z.wert), qoq: str(z.qoq), yoy: str(z.yoy), anmerkung: str(z.anmerkung) })).filter(z => z.kennzahl || z.wert);

  const g = obj(e.guidance);
  const earn = {
    quartal: str(e.quartal), quartal_betreff: str(e.quartal_betreff), zusammenfassung: str(e.zusammenfassung),
    umsatz: kopf(e.umsatz), eps: kopf(e.eps),
    umsatz_zeilen: zeilen(e.umsatz_zeilen), operative_zeilen: zeilen(e.operative_zeilen), profit_zeilen: zeilen(e.profit_zeilen),
    guidance: { status: ['angehoben', 'bestätigt', 'gesenkt', 'neu', 'keine'].includes(g.status) ? g.status : 'keine', text: str(g.text) },
    kommentar: arr(e.kommentar).map(str).filter(Boolean),
    bezug_technischer_stand: str(e.bezug_technischer_stand),
    risiken: arr(e.risiken).map(str).filter(Boolean),
    quelle_werte: ['abbildung', 'text', 'beides'].includes(e.quelle_werte) ? e.quelle_werte : (meta.earnings_bild ? 'abbildung' : 'text'),
  };
  // Gesamtergebnis: beat nur, wenn kein miss dabei ist
  const erg = [earn.umsatz.ergebnis, earn.eps.ergebnis].filter(Boolean);
  earn.ergebnis = erg.includes('miss') ? (erg.includes('beat') ? 'gemischt' : 'miss') : erg.includes('beat') ? 'beat' : erg.length ? 'inline' : '';

  // Pflichtprüfungen
  if (!earn.zusammenfassung) errors.push('Zusammenfassung fehlt');
  if (!earn.umsatz.ist && !earn.eps.ist && !earn.umsatz_zeilen.length) errors.push('Weder Umsatz noch EPS erkannt');
  if (res.stop_reason === 'max_tokens') errors.push('Antwort von Claude wurde abgeschnitten (max_tokens)');

  // Plausibilität (kein Abbruch)
  for (const [name, k] of [['Umsatz', earn.umsatz], ['EPS', earn.eps]]) {
    if (k.ist && !k.erwartung) warnings.push(`${name}: Erwartung fehlt`);
    const abw = k.abweichung.replace(/[−–]/g, '-');
    if (k.ergebnis === 'beat' && /^-/.test(abw)) warnings.push(`${name}: "beat", aber Abweichung negativ (${k.abweichung})`);
    if (k.ergebnis === 'miss' && /^\+/.test(abw)) warnings.push(`${name}: "miss", aber Abweichung positiv (${k.abweichung})`);
  }
  if (earn.quelle_werte !== 'text') warnings.push('Werte aus der Abbildung abgelesen – bitte mit der Abbildung vergleichen');
  if (!meta.earnings_bild && (meta.images || []).length) warnings.push('Abbildung konnte nicht geladen werden – nur Text ausgewertet');

  const u = res.usage || {};
  const cost = (u.input_tokens || 0) * PRICE_IN + (u.output_tokens || 0) * PRICE_OUT + (u.cache_creation_input_tokens || 0) * PRICE_CACHE_WRITE + (u.cache_read_input_tokens || 0) * PRICE_CACHE_READ;

  // Scheitert die Auswertung, geht nichts verloren: es entsteht die Platzhalter-Datei mit den Fehlern als Prüfhinweis
  if (errors.length) warnings.unshift(...errors.map(x => `Earnings-Auswertung fehlgeschlagen: ${x} – Platzhalter angelegt`));
  return { json: {
    ...meta,
    pfad: errors.length ? { ...PFAD, heute: 'Auswertung fehlgeschlagen – Platzhalter', spaeter: ['Beitrag erneut verarbeiten oder von Hand ausfüllen'] } : PFAD,
    warnings,
    earnings: errors.length ? null : earn,
    usage: { input_tokens: u.input_tokens || 0, output_tokens: u.output_tokens || 0, cost_usd: Number(cost.toFixed(6)), cost_cent: Number((cost * 100).toFixed(4)) },
  } };
});

// 2 Earnings: Anfrage an Claude bauen (v1.3)
// Claude liest die Abbildung (Earnings-Grafik) UND den Beitragstext und füllt das Earnings-Schema.
// Die Bilder kommen aus "2 Earnings: Bild laden" (gleiche Reihenfolge wie die Items aus dem Switch-Ausgang "2 Earnings").
// Fehlt ein Bild (Download fehlgeschlagen), wird nur der Text geschickt.

const MODEL = 'claude-haiku-5-5';
const PROMPT_VERSION = 'earnings-extraction-v1';
const QUELLE = $('Pfad nach Kategorie').all(1); // Ausgang 1 = "2 Earnings"

const SYSTEM = `Du bist ein Extraktionssystem für Earnings-Beiträge des Analysten "The Long Investor". Du erhältst eine Earnings-Grafik (Bild) und den Beitragstext und rufst genau einmal das Werkzeug "earnings_speichern" auf.

Regeln:
1. Übernimm nur Werte, die in der Grafik oder im Text ausdrücklich stehen. Nichts schätzen, nichts berechnen, nichts ergänzen.
2. Zahlen exakt wie abgebildet übernehmen, inklusive Vorzeichen, Einheit und Schreibweise (z. B. "$228M", "−$0.66", "+66.2%", "+411 BPS", "n/m"). Keine Umrechnung.
3. "quartal" genau wie in der Grafik (z. B. "Q1 FY27"). Steht im Betreff eine andere Quartalsangabe, kommt sie in "quartal_betreff".
4. Kopfzahlen: umsatz und eps jeweils mit ist, erwartung (est.), abweichung (z. B. "+2.2%") und ergebnis (beat | inline | miss), so wie in der Grafik angegeben. Fehlt etwas: leerer String.
5. Tabellen zeilenweise übernehmen:
   - umsatz_zeilen: Zeilen aus dem Umsatz-/Revenue-Block (inkl. Segmente)
   - profit_zeilen: Zeilen aus Profit-, Margen-, Cashflow-Blöcken; bei Margen den Blocknamen in die Kennzahl schreiben (z. B. "Bruttomarge", "Operative Marge", "Adj. EBITDA-Marge")
   - operative_zeilen: alle übrigen Kennzahlen (z. B. Nutzer, ARR, Backlog, Auslieferungen)
   Jede Zeile: kennzahl (deutsch, Fachbegriffe wie EBITDA bleiben), wert, qoq, yoy, anmerkung (deutsch, höchstens 1 Satz, Zahlen exakt).
6. guidance: status (angehoben | bestätigt | gesenkt | neu | keine) und text. "keine", wenn weder Grafik noch Text eine Prognose nennen.
7. kommentar: die Kommentar-/Commentary-Punkte des Analysten auf Deutsch, je Punkt 1 Satz, Zahlen exakt.
8. zusammenfassung: höchstens 3 Sätze auf Deutsch, sachlich, als Einschätzung des Analysten, keine eigene Bewertung.
9. bezug_technischer_stand: nur wenn der Text Chart/Kursmarken erwähnt, sonst "".
10. quelle_werte: "abbildung", "text" oder "beides" – woher die Kennzahlen stammen.
11. Alle Texte auf Deutsch.`;

const zeile = {
  type: 'object',
  properties: { kennzahl: { type: 'string' }, wert: { type: 'string' }, qoq: { type: 'string' }, yoy: { type: 'string' }, anmerkung: { type: 'string' } },
  required: ['kennzahl', 'wert'],
};
const kopf = {
  type: 'object',
  properties: { ist: { type: 'string' }, erwartung: { type: 'string' }, abweichung: { type: 'string' }, ergebnis: { type: 'string', enum: ['beat', 'inline', 'miss', ''] } },
  required: ['ist', 'erwartung', 'abweichung', 'ergebnis'],
};
const TOOL = {
  name: 'earnings_speichern',
  description: 'Speichert die strukturierten Earnings-Daten des Beitrags.',
  input_schema: {
    type: 'object',
    properties: {
      quartal: { type: 'string' },
      quartal_betreff: { type: 'string' },
      zusammenfassung: { type: 'string' },
      umsatz: kopf,
      eps: kopf,
      umsatz_zeilen: { type: 'array', items: zeile },
      operative_zeilen: { type: 'array', items: zeile },
      profit_zeilen: { type: 'array', items: zeile },
      guidance: { type: 'object', properties: { status: { type: 'string', enum: ['angehoben', 'bestätigt', 'gesenkt', 'neu', 'keine'] }, text: { type: 'string' } }, required: ['status', 'text'] },
      kommentar: { type: 'array', items: { type: 'string' } },
      bezug_technischer_stand: { type: 'string' },
      risiken: { type: 'array', items: { type: 'string' } },
      quelle_werte: { type: 'string', enum: ['abbildung', 'text', 'beides'] },
    },
    required: ['quartal', 'zusammenfassung', 'umsatz', 'eps', 'umsatz_zeilen', 'profit_zeilen', 'guidance', 'kommentar', 'quelle_werte'],
  },
};

const out = [];
const bilder = $input.all();
for (let i = 0; i < QUELLE.length; i++) {
  const p = QUELLE[i].json;
  const content = [];
  const bin = bilder[i] && bilder[i].binary && bilder[i].binary.data;
  let bild = false;
  if (bin) {
    const mt = String(bin.mimeType || '').toLowerCase();
    const mediaType = /jpe?g/.test(mt) ? 'image/jpeg' : /gif/.test(mt) ? 'image/gif' : /webp/.test(mt) ? 'image/webp' : 'image/png';
    const data = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64');
    content.push({ type: 'image', source: { type: 'base64', media_type: mediaType, data } });
    bild = true;
  }
  content.push({ type: 'text', text: [
    `Betreff: ${p.subject}`,
    `Ticker: ${p.ticker_hint || 'unbekannt'}`,
    `Veröffentlicht: ${p.published_date || 'unbekannt'}`,
    bild ? 'Die Earnings-Grafik ist oben angehängt.' : 'Keine Grafik verfügbar – nur Text auswerten.',
    '',
    'Beitragstext:',
    p.body_clean || '(kein Text)',
  ].join('\n') });

  out.push({ json: {
    ...p,
    earnings_bild: bild,
    model: MODEL,
    prompt_version: PROMPT_VERSION,
    request: {
      model: MODEL,
      max_tokens: 3000,
      system: [{ type: 'text', text: SYSTEM, cache_control: { type: 'ephemeral' } }],
      tools: [TOOL],
      tool_choice: { type: 'tool', name: 'earnings_speichern' },
      messages: [{ role: 'user', content }],
    },
  } });
}
return out;

// 3 Bewertung (v1.6): Beiträge mit PDF werden in Flow A NICHT ausgewertet.
// Die PDF ist kein echter Gmail-Anhang, sondern ein Patreon-Link (Login nötig) – die Auswertung folgt in einem eigenen Flow.
// Hier bekommt die Mail nur das Label Kategorie3_PDF und verlässt den Eingang. Keine Datei, kein Claude-Aufruf.
const labels = $('Gmail: Labels holen').all().map(i => i.json);
const byName = n => labels.find(l => String(l.name).toLowerCase() === n.toLowerCase());
const ziel = byName('FinVault/Kategorie3_PDF') || byName('Kategorie3_PDF');
if (!ziel) throw new Error('Gmail-Label "Kategorie3_PDF" fehlt – bitte in Gmail anlegen (unter FinVault oder auf oberster Ebene).');
const eingang = ['FinVault/Eingang', 'FinVault/Eingang_jakob'].map(byName).filter(Boolean).map(l => l.id);
return $input.all().map(i => ({ json: {
  gmail_message_id: i.json.gmail_message_id,
  subject: i.json.subject,
  ticker: i.json.ticker_hint || '',
  published_date: i.json.published_date,
  ziel_label: ziel.name,
  ziel_label_id: ziel.id,
  eingang_label_ids: eingang,
} }));

// 4 Grafiken & Kalender (Platzhalter) (v1.0)
// Dieser Pfad ist eingerichtet. Heute: Platzhalter-Datei nach Template Analysten-Grafik-Kalender (Originaltext + Abbildungen).
// Später geplant:
//   1. Abbildung mit Claude (Bildanalyse) auswerten
//   2. Infografik: Kernaussagen · Kalender: Termine-Tabelle füllen
//   3. Ablage für Kalender ohne Ticker festlegen
//   4. Erwähnte Wertpapiere verlinken
// Der Node markiert nur den Pfad; Datei bzw. Gmail-Label setzt "Zieldatei bestimmen".
const PFAD = {
  "kategorie": "4 Grafiken & Kalender",
  "ziel": "<TICKER>/4 Grafiken & Kalender",
  "template": "Analysten-Grafik-Kalender",
  "heute": "Platzhalter-Datei nach Template Analysten-Grafik-Kalender (Originaltext + Abbildungen)",
  "spaeter": [
    "Abbildung mit Claude (Bildanalyse) auswerten",
    "Infografik: Kernaussagen · Kalender: Termine-Tabelle füllen",
    "Ablage für Kalender ohne Ticker festlegen",
    "Erwähnte Wertpapiere verlinken"
  ]
};
return $input.all().map(i => ({ json: { ...i.json, pfad: PFAD } }));

// 5 Markt & Makro (Platzhalter) (v1.0)
// Dieser Pfad ist eingerichtet. Heute: Platzhalter-Datei nach Template Analysten-Markt-Makro (Originaltext + Abbildungen).
// Später geplant:
//   1. Claude extrahiert Indikatoren (Wert, Vorwert, Erwartung) und Einordnung
//   2. Template Analysten-Markt-Makro füllen
//   3. Betroffene Wertpapiere und vorherigen Beitrag zum Thema verlinken
// Der Node markiert nur den Pfad; Datei bzw. Gmail-Label setzt "Zieldatei bestimmen".
const PFAD = {
  "kategorie": "5 Markt & Makro",
  "ziel": "5 Markt & Makro",
  "template": "Analysten-Markt-Makro",
  "heute": "Platzhalter-Datei nach Template Analysten-Markt-Makro (Originaltext + Abbildungen)",
  "spaeter": [
    "Claude extrahiert Indikatoren (Wert, Vorwert, Erwartung) und Einordnung",
    "Template Analysten-Markt-Makro füllen",
    "Betroffene Wertpapiere und vorherigen Beitrag zum Thema verlinken"
  ]
};
return $input.all().map(i => ({ json: { ...i.json, pfad: PFAD } }));

// 6 Newsletter (Platzhalter) (v1.0)
// Dieser Pfad ist eingerichtet. Heute: Platzhalter-Datei nach Template Analysten-Newsletter (Originaltext + Abbildungen).
// Später geplant:
//   1. Newsletter in einzelne Meldungen zerlegen
//   2. Je Meldung Thema, Wertpapiere, Kernaussagen, TL;DR
//   3. Erwähnungen in den Wertpapier-Übersichten eintragen
//   4. Vorherige Ausgabe verlinken
// Der Node markiert nur den Pfad; Datei bzw. Gmail-Label setzt "Zieldatei bestimmen".
const PFAD = {
  "kategorie": "6 Newsletter",
  "ziel": "6 Newsletter",
  "template": "Analysten-Newsletter",
  "heute": "Platzhalter-Datei nach Template Analysten-Newsletter (Originaltext + Abbildungen)",
  "spaeter": [
    "Newsletter in einzelne Meldungen zerlegen",
    "Je Meldung Thema, Wertpapiere, Kernaussagen, TL;DR",
    "Erwähnungen in den Wertpapier-Übersichten eintragen",
    "Vorherige Ausgabe verlinken"
  ]
};
return $input.all().map(i => ({ json: { ...i.json, pfad: PFAD } }));

// 8 Sonstige (Platzhalter) (v1.0)
// Dieser Pfad ist eingerichtet. Heute: Platzhalter-Datei nach Template Analysten-Sonstige (Originaltext + Abbildungen).
// Später geplant:
//   1. Kurze Zusammenfassung und Kernaussagen (optional mit Claude)
//   2. Erwähnte Wertpapiere verlinken
// Der Node markiert nur den Pfad; Datei bzw. Gmail-Label setzt "Zieldatei bestimmen".
const PFAD = {
  "kategorie": "8 Sonstige",
  "ziel": "8 Sonstige",
  "template": "Analysten-Sonstige",
  "heute": "Platzhalter-Datei nach Template Analysten-Sonstige (Originaltext + Abbildungen)",
  "spaeter": [
    "Kurze Zusammenfassung und Kernaussagen (optional mit Claude)",
    "Erwähnte Wertpapiere verlinken"
  ]
};
return $input.all().map(i => ({ json: { ...i.json, pfad: PFAD } }));

// 9 Manuelle Prüfung (v1.0)
// Dieser Pfad ist eingerichtet. Heute: Platzhalter-Datei nach Template Analysten-Sonstige (Originaltext + Abbildungen).
// Später geplant:
//   1. Optional: Claude schlägt eine Kategorie vor
//   2. Nach Prüfung von Hand in den richtigen Ordner verschieben
// Der Node markiert nur den Pfad; Datei bzw. Gmail-Label setzt "Zieldatei bestimmen".
const PFAD = {
  "kategorie": "9 Manuelle Prüfung",
  "ziel": "9 Manuelle Prüfung",
  "template": "Analysten-Sonstige",
  "heute": "Platzhalter-Datei nach Template Analysten-Sonstige (Originaltext + Abbildungen)",
  "spaeter": [
    "Optional: Claude schlägt eine Kategorie vor",
    "Nach Prüfung von Hand in den richtigen Ordner verschieben"
  ]
};
return $input.all().map(i => ({ json: { ...i.json, pfad: PFAD } }));

// Abbildung vorbereiten (v0.9)
// Verbindet die heruntergeladenen Bilder mit Zielpfad/Dateiname aus "Bild?" (true-Zweig).
// Fehlgeschlagene Downloads (ohne Binärdaten) werden übersprungen.
const src = $('Bild?').all(0);
return $input.all()
  .map((it, i) => ({ json: { ...src[i].json }, binary: it.binary }))
  .filter(x => x.binary && x.binary.data)
  .map(x => { x.binary.data.fileName = x.json.file_name; return x; });

// Älteste zuerst (v1.4)
// Gmail liefert die neuesten Mails zuerst. Damit Updates in Datumsreihenfolge ankommen (sonst entstehen
// "Nachträge" im Status), werden alle Mails im Eingang nach Veröffentlichungsdatum sortiert und je Lauf
// nur die 20 ältesten verarbeitet. Die übrigen bleiben im Eingang und kommen beim nächsten Lauf dran.
const MAX = 20;
const alle = $input.all().map(i => i.json);
alle.sort((a, b) => (String(a.published_date || '9999') + String(a.email_date || '')).localeCompare(String(b.published_date || '9999') + String(b.email_date || '')));
const verbleibend = Math.max(0, alle.length - MAX);
return alle.slice(0, MAX).map(j => ({ json: { ...j, im_eingang_verbleibend: verbleibend } }));

// Baustein 2b: Antwort von Claude prüfen (v0.6)
// Holt das JSON aus der Werkzeug-Antwort, normalisiert sicher Normalisierbares
// und prüft die Regeln aus dem Datenvertrag. Ergebnis: ok=true/false + errors/warnings.

const PRICE_IN = 0.10 / 1e6;   // Haiku 5.5, USD pro Input-Token (Prompt < 100k)
const PRICE_OUT = 0.50 / 1e6;  // USD pro Output-Token
const PRICE_CACHE_WRITE = 0.125 / 1e6; // Cache schreiben (5 Min.)
const PRICE_CACHE_READ = 0.01 / 1e6;   // Cache lesen
const CATEGORIES = ['Technisch', 'Fundamental', 'Sonstige'];

const sources = $('Prompt bauen').all();
const lookup = $('Register vorbereiten').first().json.concept_lookup || {};
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

return $input.all().map((item, i) => {
  const res = item.json;
  const src = sources[i] ? sources[i].json : {};
  const { request, ...meta } = src;
  const errors = [];
  const warnings = [];

  const toolUse = (res.content || []).find(c => c.type === 'tool_use');
  let a = toolUse ? JSON.parse(JSON.stringify(toolUse.input)) : null;
  if (!a || typeof a !== 'object') {
    errors.push('Keine strukturierte Antwort von Claude erhalten');
    a = {};
  }

  // --- beschädigte Antworten reparieren ---
  // Selten rutscht Werkzeug-Syntax wie '</feld>\n<parameter name="x">...' in ein Textfeld.
  // Dann: Wert vor dem Tag behalten, mitgeschleppte Parameter dem richtigen Feld zuordnen.
  let repaired = false;
  const LEAK = /<\/?(parameter|invoke|antml|[a-z_]+>)/i;
  for (const key of Object.keys(a)) {
    const val = a[key];
    if (typeof val !== 'string' || !LEAK.test(val)) continue;
    repaired = true;
    const cut = val.search(/<\/?[a-z_]+[\s>]/i);
    a[key] = val.slice(0, cut).trim();
    for (const m of val.matchAll(/<parameter name="([a-z_]+)">([\s\S]*?)(?=<\/?parameter|<\/[a-z_]+>|$)/gi)) {
      const field = m[1], raw = m[2].trim();
      const empty = a[field] == null || a[field] === '' || (Array.isArray(a[field]) && !a[field].length);
      if (empty) { try { a[field] = JSON.parse(raw); } catch (e) { a[field] = raw; } }
    }
  }
  const stripTags = s => String(s).replace(/<\/?[a-z_]+(\s[^>]*)?>/gi, '').trim();
  const deep = x => Array.isArray(x) ? x.map(deep) : (x && typeof x === 'object')
    ? Object.fromEntries(Object.entries(x).map(([k, y]) => [k, deep(y)]))
    : (typeof x === 'string' ? stripTags(x) : x);
  a = deep(a);

  // --- sicher normalisierbar ---
  const arr = v => {
    if (Array.isArray(v)) return v.filter(x => x !== '' && x !== '[]' && x != null);
    if (v == null || v === '' || v === '[]') return [];
    if (typeof v === 'string' && v.trim().startsWith('[')) { try { const p = JSON.parse(v); if (Array.isArray(p)) return p; } catch (e) {} }
    return [v];
  };
  for (const k of ['analysis_types', 'supports', 'resistances', 'observation_zones', 'invalidations', 'targets', 'other_levels',
    'fundamental_statements', 'upcoming_events', 'reevaluation_conditions', 'uncertainties_and_risks',
    'mentioned_tickers', 'missing_information', 'recognized_concepts']) a[k] = arr(a[k]);
  a.ticker = String(a.ticker || '').replace(/^\$/, '').trim().toUpperCase();
  a.mentioned_tickers = a.mentioned_tickers.map(t => String(t).replace(/^\$/, '').toUpperCase()).filter(t => t && t !== a.ticker);
  if (a.main_category) {
    const c = String(a.main_category).trim();
    a.main_category = CATEGORIES.find(x => x.toLowerCase() === c.toLowerCase()) || c;
  }
  for (const k of ['supports', 'resistances', 'invalidations', 'targets', 'other_levels']) {
    a[k] = a[k].map(l => ({ ...l, level: (l && l.level != null && l.level !== '') ? Number(l.level) : null, currency: (l && l.currency) || (l && l.level != null ? 'USD' : '') }));
  }

  // --- Pflichtprüfungen ---
  if (!CATEGORIES.includes(a.main_category)) errors.push(`Unbekannte Kategorie: ${a.main_category}`);
  if (['Technisch', 'Fundamental'].includes(a.main_category) && !/^[A-Z][A-Z0-9.]{0,6}$/.test(a.ticker)) errors.push(`Ungültiger oder fehlender Ticker: "${a.ticker}"`);
  if (!a.summary) errors.push('Zusammenfassung fehlt');
  for (const k of ['supports', 'resistances', 'invalidations', 'targets']) {
    a[k].forEach((l, j) => { if (l.level !== null && !Number.isFinite(l.level)) errors.push(`${k}[${j}]: Kurs ist keine Zahl`); });
  }

  // --- Warnungen (kein Abbruch, aber im Review sichtbar) ---
  if (meta.ticker_hint && a.ticker && meta.ticker_hint !== a.ticker) warnings.push(`Ticker weicht vom Betreff ab: Betreff ${meta.ticker_hint}, Claude ${a.ticker}`);
  const body = String(meta.body_clean || '');
  const allLevels = ['supports', 'resistances', 'invalidations', 'targets', 'other_levels'].flatMap(k => a[k].map(l => l.level)).filter(v => v !== null);
  for (const v of allLevels) {
    const plain = String(v);
    const withComma = plain.replace('.', ',');
    if (!body.includes(plain) && !body.includes(withComma)) warnings.push(`Kursmarke ${v} kommt im Originaltext nicht wörtlich vor – bitte prüfen`);
  }
  for (const z of a.observation_zones) for (const v of [z.from, z.to]) {
    if (v != null && !body.includes(String(v)) && !body.includes(String(v).replace('.', ','))) warnings.push(`Zonengrenze ${v} kommt im Originaltext nicht wörtlich vor – bitte prüfen`);
  }
  const lv = k => new Set(a[k].map(l => l.level).filter(v => v !== null));
  for (const v of lv('supports')) if (lv('resistances').has(v)) warnings.push(`Kursmarke ${v} ist gleichzeitig Unterstützung und Widerstand`);
  if (res.stop_reason === 'max_tokens') errors.push('Antwort von Claude wurde abgeschnitten (max_tokens)');

  // --- Begriffe gegen das Register prüfen -> Links zur Theorie ---
  const conceptLinks = [];
  const seen = new Set();
  for (const c of a.recognized_concepts) {
    const hit = lookup[norm(c)];
    if (!hit) { warnings.push(`Begriff "${c}" steht nicht im Register – kein Link`); continue; }
    if (seen.has(hit.zielpfad)) continue;
    seen.add(hit.zielpfad);
    conceptLinks.push(hit);
  }

  if (repaired) warnings.push('Claude-Antwort enthielt fehlerhafte Steuerzeichen – automatisch bereinigt, bitte Inhalte prüfen');
  if (meta.warnings && meta.warnings.length) warnings.unshift(...meta.warnings);

  const usage = res.usage || {};
  const cost = (usage.input_tokens || 0) * PRICE_IN + (usage.output_tokens || 0) * PRICE_OUT
    + (usage.cache_creation_input_tokens || 0) * PRICE_CACHE_WRITE + (usage.cache_read_input_tokens || 0) * PRICE_CACHE_READ;

  return {
    json: {
      ...meta,
      ok: errors.length === 0 && meta.ok !== false,
      errors: [...(meta.errors || []), ...errors],
      warnings,
      analysis: a,
      concept_links: conceptLinks,
      usage: { input_tokens: usage.input_tokens || 0, output_tokens: usage.output_tokens || 0, cache_write_tokens: usage.cache_creation_input_tokens || 0, cache_read_tokens: usage.cache_read_input_tokens || 0, cost_usd: Number(cost.toFixed(6)), cost_cent: Number((cost * 100).toFixed(4)) },
    },
  };
});

// Beitrag einordnen (v1.0) – regelbasiert, ohne KI
// Entscheidungsbaum laut Prozessübersicht (Reihenfolge = Priorität, erster Treffer gewinnt):
//   0 Nicht verarbeitet (fremder Absender) · 7 Video · 6 Newsletter · 2 Earnings · 3 Bewertung
//   4 Grafiken & Kalender · 5 Markt & Makro · 1 Analyse · 9 Manuelle Prüfung · 8 Sonstige
// Nur Kategorie 1 (mit Ticker) geht an Claude. Alle anderen bekommen vorerst eine Platzhalter-Datei.

const KATEGORIEN = {
  0: 'Nicht verarbeitet', 1: 'Analyse', 2: 'Earnings', 3: 'Bewertung', 4: 'Grafiken & Kalender',
  5: 'Markt & Makro', 6: 'Newsletter', 7: 'Video', 8: 'Sonstige', 9: 'Manuelle Prüfung',
};

// Regeln in Prioritätsreihenfolge. test(t) bekommt den normalisierten Titel (Originalschreibweise).
const REGELN = [
  { nr: 7, regel: 'video', test: t => /\bvideos?\b/i.test(t) },
  { nr: 6, regel: 'newsletter', test: t => /\bthe\s+lit\s+(sunday\s+)?(news|newsletter)\b|\bnewsletter\b/i.test(t) },
  { nr: 2, regel: 'earnings', test: t => /\bearnings?\s+results?\b/i.test(t) || /\bresults?\b/i.test(t) || /\bER\b/.test(t)
      || (/\bearnings?\b/i.test(t) && !/\b(calendar|kalender)\b/i.test(t)) },
  { nr: 3, regel: 'bewertung', test: t => /\bvaluation\b|\bfair\s+value\b|\bbewertung\b/i.test(t) },
  { nr: 4, regel: 'grafik_kalender', test: t => /\binfographics?\b|\b(earnings\s+)?calendar\b|\bkalender\b/i.test(t) },
  { nr: 5, regel: 'makro', test: t => /\b(treasury|bonds?|yields?|\d{1,2}-year|inflation|fed|fomc|cpi|ppi|pce|gdp|macro|makro|interest\s+rates?|rate\s+(cut|hike)s?|jobs\s+report|payrolls?|unemployment)\b/i.test(t) },
  { nr: 1, regel: 'analyse', test: t => TICKER_START.test(t) || /\b(watchlist|buy\s+zone|important\s+level|top\s+(10|20)|safe\s+haven|elliott\s+wave|ew\s+count|wave\s+count)\b/i.test(t) },
];
// Ticker am Titelanfang: "$UBER …" oder "UBER - …" (Großbuchstaben, case-sensitiv)
const TICKER_START = /^(\$[A-Z][A-Z0-9.]{0,6}\b|[A-Z]{1,5}(\.[A-Z])?\s*[-–:|])/;
const TICKER_ANY = /\$([A-Z][A-Z0-9.]{0,6})\b/;

// Betreff normalisieren: Weiterleitungs- und Patreon-Präfixe entfernen
function titel(subject) {
  return String(subject || '')
    .replace(/^\s*((fwd?|fw|wg|aw|re)\s*:\s*)+/i, '')
    .replace(/^\s*\[?patreon\]?\s*[:\-–]\s*/i, '')
    .replace(/^\s*(new post from|neuer (beitrag|post) von)\s+the long investor\s*[:\-–]?\s*/i, '')
    .replace(/^\s*the long investor\s+(posted|hat gepostet|hat einen beitrag veröffentlicht)\s*[:\-–]?\s*/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function tickerAus(t) {
  const m = t.match(TICKER_ANY);
  if (m) return m[1];
  const s = t.match(/^([A-Z]{1,5}(\.[A-Z])?)\s*[-–:|]/);
  return s ? s[1] : '';
}

return $input.all().map(item => {
  const p = item.json;
  const t = titel(p.subject);
  const errors = [...(p.errors || [])];
  const warnings = [...(p.warnings || [])];
  let nr, regel, grund = '';

  // Absender prüfen: muss ein Patreon-Beitrag von The Long Investor sein (auch bei Weiterleitung)
  const quelle = `${p.original_from || ''} ${p.post_url || ''}`;
  const istPatreon = /patreon/i.test(quelle);
  const istTLI = /long\s*investor|thelonginvestor/i.test(quelle);
  const treffer = REGELN.filter(r => r.test(t));
  const ticker = tickerAus(t);

  if (!istPatreon || !istTLI) {
    nr = 0; regel = 'absender'; grund = `Absender/Link nicht als Patreon-Beitrag von The Long Investor erkennbar (${(p.original_from || 'unbekannt').slice(0, 80)})`;
  } else if (treffer.length) {
    nr = treffer[0].nr; regel = treffer[0].regel;
  } else if (!t || t.replace(/[^A-Za-z0-9]/g, '').length < 3) {
    nr = 9; regel = 'titel_unklar'; grund = 'Betreff leer oder zu kurz';
  } else if (ticker) {
    nr = 9; regel = 'ticker_ohne_art'; grund = `Ticker $${ticker} im Titel, aber keine eindeutige Beitragsart`;
  } else {
    nr = 8; regel = 'kein_treffer';
  }

  // Kategorien, die einem Wertpapier zugeordnet werden, brauchen einen Ticker
  if ([1, 2, 3, 4].includes(nr) && !ticker) {
    grund = `Kategorie ${nr} ${KATEGORIEN[nr]} erkannt (Regel "${regel}"), aber kein Ticker im Titel – Ablageort unklar`;
    regel = `${regel}_ohne_ticker`; nr = 9;
  }

  // Fehler aus "Mail bereinigen", die nach der Einordnung nicht mehr gelten
  const rest = errors.filter(e => {
    if (/nicht Patreon/i.test(e)) return false;                       // übernimmt die Absenderprüfung oben
    if (/zu kurz/i.test(e) && nr !== 1) return false;                  // Platzhalter brauchen keinen Mindesttext (z. B. Infografiken)
    return true;
  });
  // Analyse (Ticker am Titelanfang) passt bei fast jedem Wertpapier-Beitrag mit – nicht als Konflikt melden
  const weitere = treffer.slice(1).filter(r => r.nr !== 1).map(r => `${r.nr} ${KATEGORIEN[r.nr]}`);
  if (weitere.length && nr === treffer[0].nr) warnings.push(`Titel passt auch zu: ${weitere.join(', ')} – nach Priorität als ${nr} ${KATEGORIEN[nr]} eingeordnet`);

  const ok = rest.length === 0;
  return {
    json: {
      ...p,
      titel: t,
      kategorie_nr: nr,
      kategorie: KATEGORIEN[nr],
      regel,
      einordnung_grund: grund,
      weitere_treffer: weitere,
      ticker_hint: ticker || p.ticker_hint || '',
      ki: ok && nr === 1,
      ok,
      errors: rest,
      warnings,
    },
  };
});

// Bestand auswerten (v0.7)
// Liest die vorhandenen Update-Dateien (vom Node "Bestand lesen") und merkt sich je Datei:
// Name, Pfad, Ticker, Datum, Gmail-ID und Inhalt -> für Dubletten, Vorgänger/Nachfolger und deren Korrektur.

function frontmatter(text) {
  const m = text.match(/^---\s*\n([\s\S]*?)\n---/);
  const fm = {};
  if (!m) return fm;
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z_äöüÄÖÜ]+):\s*(.*)$/);
    if (kv) fm[kv[1]] = kv[2].replace(/^["']|["']$/g, '').trim();
  }
  return fm;
}

const existing = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) continue;
  if (!/^\d{4}-\d{2}-\d{2} - /.test(bin.fileName || '')) continue; // nur Update-Dateien
  const text = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  const fm = frontmatter(text);
  const fileName = bin.fileName || '';
  const nameMatch = fileName.match(/^(\d{4}-\d{2}-\d{2}) - ([^ ]+) - /);
  existing.push({
    name: fileName.replace(/\.md$/i, ''),
    file_name: fileName,
    directory: bin.directory || '',
    ticker: String(fm.ticker || (nameMatch ? nameMatch[2] : '')).toUpperCase(),
    date: fm.veroeffentlicht || fm['veröffentlicht'] || (nameMatch ? nameMatch[1] : ''),
    gmail_message_id: fm.gmail_message_id || '',
    neues_format: fm.schema_version === '1.0',
    content: text,
  });
}
return [{ json: { existing_count: existing.length, existing } }];

