// Register + Templates vorbereiten (v1.0)
// Eingang: concept-links.json UND alle Templates/Analysten-*.md (Merge "Register + Template")
// templates: { 'Analysten-Update': '…', 'Analysten-Earnings': '…', … } für die Platzhalter je Kategorie
// Liest concept-links.json (vom Node "Register lesen") und baut
// 1) eine kompakte Begriffsliste für Claude (nach Hauptthema gruppiert)
// 2) ein Nachschlage-Verzeichnis Begriff/Alias -> Zielnotiz für die Link-Prüfung

let reg = null, template = '';
const templates = {};
const ins = $input.all();
for (let i = 0; i < ins.length; i++) {
  const bin = ins[i].binary && ins[i].binary.data;
  if (!bin) continue;
  const text = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  if (/\.json$/i.test(bin.fileName || '')) reg = JSON.parse(text);
  else if (/\.md$/i.test(bin.fileName || '')) {
    const name = String(bin.fileName).normalize('NFC').replace(/\.md$/i, '');
    templates[name] = text;
    if (name === 'Analysten-Update') template = text;
  }
}
if (!reg) throw new Error('concept-links.json nicht gefunden');
if (!template) throw new Error('Template Trading/Templates/Analysten-Update.md nicht gefunden');
const konzepte = Array.isArray(reg.konzepte) ? reg.konzepte : [];
if (!konzepte.length) throw new Error('concept-links.json enthält keine Konzepte');

const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

const lookup = {};
const groups = {};
for (const k of konzepte) {
  if (!k.begriff || !k.zielpfad) continue;
  const entry = { begriff: k.begriff, zielpfad: k.zielpfad, hauptthema: k.hauptthema || '', prioritaet: k.prioritaet || '' };
  for (const name of [k.begriff, ...(k.aliases || [])]) {
    const key = norm(name);
    if (key && (!lookup[key] || k.primaer)) lookup[key] = entry;
  }
  if (k.primaer !== false) {
    const g = `${String(k.hauptthema_nummer || '').padStart(2, '0')} ${k.hauptthema || 'Sonstige'}`;
    (groups[g] = groups[g] || []).push(k.begriff);
  }
}

// Hauptthemen -> Übersichtsnotiz (Fallback laut Register-Regel "fallback_auf_hauptthema_index")
const themen = Array.isArray(reg.hauptthemen) ? reg.hauptthemen : [];
for (const h of themen) {
  if (!h.hauptthema || !h.zielpfad) continue;
  const key = norm(h.hauptthema);
  if (!lookup[key]) lookup[key] = { begriff: h.hauptthema, zielpfad: h.zielpfad, hauptthema: h.hauptthema, prioritaet: 'Hauptthema' };
}

const list = 'Hauptthemen (Übersichtsnotizen): ' + themen.map(h => h.hauptthema).join('; ') + '\n' + Object.keys(groups).sort()
  .map(g => `${g}: ${[...new Set(groups[g])].join('; ')}`)
  .join('\n');

return [{
  json: {
    register_version: reg.schema_version || '',
    concept_count: konzepte.length,
    concept_list: list,
    concept_lookup: lookup,
    template,
    templates,
  },
}];

// Status-Aufträge für Flow B (v1.4)
// Nur neu geschriebene Analyse-Updates (<TICKER>/1 technische Analyse/Updates).
// Neuaufbau bei Nachträgen: Ist ein neues Update älter als ein schon vorhandenes Update desselben Tickers,
// würde Flow B es nur als "Nachtrag" ergänzen (ohne Abgleich gegen das neuere Update).
// Dann schicken wir stattdessen ALLE Updates dieses Tickers in Datumsreihenfolge an Flow B;
// das erste trägt neuaufbau=true -> Flow B baut den Status von vorne auf (alter Stand wird gesichert).
const RE = /\/([^/]+)\/1 technische Analyse\/Updates\/[^/]+\.md$/;
const neuFormat = txt => { const m = String(txt || '').match(/workflow:\s*"?FinVault Patreon → Vault v(\d+)\.(\d+)/); return !!m && (Number(m[1]) > 0 || Number(m[2]) >= 8); };
const datumAus = p => p.split('/').pop().slice(0, 10);

const neu = $('Zieldatei bestimmen').all().map(i => i.json)
  .filter(j => j.kind === 'datei' && j.art === 'neu' && RE.test(j.target_path));
const bestand = $('Bestand auswerten').first().json.existing || [];

const proTicker = {};
for (const j of neu) { const T = j.target_path.match(RE)[1]; (proTicker[T] = proTicker[T] || []).push(j.target_path); }

const jobs = [];
for (const [T, pfade] of Object.entries(proTicker)) {
  const dir = pfade[0].slice(0, pfade[0].lastIndexOf('/'));
  const vorhanden = bestand
    .filter(e => e.directory === dir && /^\d{4}-\d{2}-\d{2} - /.test(e.file_name || '') && neuFormat(e.content))
    .map(e => `${e.directory}/${e.file_name}`)
    .filter(p => !pfade.includes(p));
  const key = p => datumAus(p) + p;
  const neuestesVorhanden = vorhanden.map(key).sort().pop() || '';
  const nachtrag = pfade.some(p => key(p) < neuestesVorhanden);
  if (nachtrag) {
    const alle = [...new Set([...vorhanden, ...pfade])].sort((a, b) => key(a).localeCompare(key(b)));
    alle.forEach((p, i) => jobs.push({ update_path: p, neuaufbau: i === 0, grund: i === 0 ? `Nachtrag ${pfade.filter(x => key(x) < neuestesVorhanden).map(datumAus).join(', ')} älter als ${neuestesVorhanden.slice(0, 10)}` : '' }));
  } else {
    pfade.forEach(p => jobs.push({ update_path: p, neuaufbau: false }));
  }
}
return jobs.map(j => ({ json: j }));

// Baustein 3: Dateien nach Template bauen + Reihenfolge pflegen (v1.5)
// - Ablage nach Ordnerstruktur v1.0 (Research/Analysten/The Long Investor):
//     1 Analyse            -> <TICKER>/1 technische Analyse/Updates   (Template Analysten-Update, Inhalt von Claude)
//     2 Earnings           -> <TICKER>/2 Earnings                     (Template Analysten-Earnings, Inhalt von Claude aus Grafik + Text)
//     3 Bewertung          -> <TICKER>/3 Bewertung                    (Template Analysten-Bewertung, Inhalt von Claude aus dem PDF-Text)
//     4 Grafiken & Kalender-> <TICKER>/4 Grafiken & Kalender           (Platzhalter, Analysten-Grafik-Kalender)
//     5 Markt & Makro      -> 5 Markt & Makro                         (Platzhalter, Analysten-Markt-Makro)
//     6 Newsletter         -> 6 Newsletter                            (Platzhalter, Analysten-Newsletter)
//     8 Sonstige           -> 8 Sonstige                              (Platzhalter, Analysten-Sonstige)
//     9 Manuelle Prüfung   -> 9 Manuelle Prüfung                      (Originaltext + Grund)
//     7 Video / 0 fremder Absender -> keine Datei, nur Gmail-Label FinVault/Ignoriert
// - Platzhalter: Frontmatter + Überschriften exakt aus dem Kategorie-Template, Originaltext und Abbildungen
//   werden übernommen, inhaltliche Abschnitte bleiben leer (Auswertung je Kategorie folgt später).
// - Dublettenschutz über gmail_message_id (über alle Kategorien), keine Überschreibung vorhandener Dateien
// - Vorgänger/Nachfolger für Analyse-Updates, Earnings und Bewertungen; bei Nachträgen werden NUR diese Felder in den Nachbarn korrigiert
// - Abbildungen: werden nach Trading/Media/Analysten/The Long Investor heruntergeladen und eingebettet
// Ausgabe: kind="datei" (Markdown), kind="bild" (Download), kind="mail" (Ergebnis je Mail)

const ROOT = '/vault/Finanzen/Trading/Research/Analysten/The Long Investor';
const MEDIA = '/vault/Finanzen/Trading/Media/Analysten/The Long Investor';
const WORKFLOW = 'FinVault Patreon → Vault v1.5';
const REG = $('Register vorbereiten').first().json;
const TEMPLATE = REG.template;
const TEMPLATES = REG.templates || {};
const bestand = ($('Bestand auswerten').first().json.existing || []).map(e => ({ ...e, path: e.directory ? `${e.directory}/${e.file_name}` : '' }));

const esc = s => String(s == null ? '' : s).replace(/</g, '&lt;').replace(/>/g, '&gt;');
const safe = s => String(s || '').replace(/[^A-Za-z0-9 ._-]/g, '').trim();
const q = s => JSON.stringify(s == null ? '' : String(s));
const wl = name => name ? `[[${name}]]` : '';
const num = v => (v == null || v === '') ? '' : `${Number(v).toLocaleString('de-DE', { maximumFractionDigits: 2 })}`;
const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const lines = arr => (arr || []).filter(Boolean).map(x => `- ${esc(x)}`).join('\n');
const levelLines = list => (list || []).map(l => {
  const price = l.level != null ? `${num(l.level)} ${l.currency || 'USD'}` : '';
  const text = [price, esc(l.label)].filter(Boolean).join(' – ');
  return `- ${text}${l.note ? ` (${esc(l.note)})` : ''}`;
}).join('\n');
const zoneLines = list => (list || []).map(z => {
  const range = (z.from != null && z.to != null && z.from !== z.to) ? `${num(z.from)} – ${num(z.to)}` : num(z.from != null ? z.from : z.to);
  return `- ${[range ? `${range} ${z.currency || 'USD'}` : '', esc(z.label)].filter(Boolean).join(' – ')}`;
}).join('\n');
const join = (...parts) => parts.filter(p => p && String(p).trim()).join('\n\n');

// ---------- Template zerlegen ----------
function parseTemplate(t) {
  const txt = String(t).replace(/\r/g, '').split('\n').map(l => l.replace(/\s+$/, '')).join('\n');
  const m = txt.match(/^---\s*\n([\s\S]*?)\n---\s*\n?([\s\S]*)$/);
  const fmKeys = [];
  if (m) for (const l of m[1].split('\n')) { const k = l.match(/^([^\s:#-][^:]*):/); if (k) fmKeys.push(k[1].trim()); }
  const body = m ? m[2] : txt;
  const blocks = []; // {level, title, lines[]} ; level 1 = Titel
  let cur = null;
  for (const l of body.split('\n')) {
    const h = l.match(/^(#{1,6})\s+(.*)$/);
    if (h) { cur = { level: h[1].length, title: h[2].trim(), lines: [] }; blocks.push(cur); continue; }
    if (cur && l.trim()) cur.lines.push(l);
  }
  return { fmKeys, blocks };
}
const TPL = parseTemplate(TEMPLATE);
const fmKey = (...alts) => TPL.fmKeys.find(k => alts.includes(norm(k))) || alts[0];
const KEY_VOR = fmKey('vorganger', 'vorgaenger');
const KEY_NACH = fmKey('nachfolger');

// ---------- Inhalte je Abschnitt (Zuordnung über die Überschrift) ----------
function sectionContent(title, ctx) {
  const { p, a, ticker, images } = ctx;
  const t = norm(title);
  if (t === 'zusammenfassung') return esc(a.summary);
  if (t.startsWith('marktstand')) return join(esc(a.market_state), esc(a.trend_structure), levelLines(a.other_levels));
  if (t === 'technisches szenario') return '';
  if (t === 'primarszenario') return esc(a.primary_scenario);
  if (t === 'alternatives szenario') return esc(a.alternative_scenario);
  if (t.startsWith('unterstutzung')) return levelLines(a.supports);
  if (t.startsWith('widerstand')) return levelLines(a.resistances);
  if (t.startsWith('kauf')) return zoneLines(a.observation_zones);
  if (t.startsWith('invalidation')) return levelLines(a.invalidations);
  if (t.startsWith('kursziel')) return levelLines(a.targets);
  if (t.startsWith('elliott')) return esc(a.elliott_wave);
  if (t.startsWith('fundamental')) return lines(a.fundamental_statements);
  if (t.startsWith('anderungen gegenuber')) return '';
  if (t.startsWith('bedingungen')) return lines([...(a.reevaluation_conditions || []), ...(a.upcoming_events || []).map(e => `Termin: ${e}`)]);
  if (t.startsWith('unsicherheiten')) return lines([...(a.uncertainties_and_risks || []), ...(a.missing_information || []).map(x => `Nicht genannt: ${x}`)]);
  if (t.startsWith('originalabbildungen')) {
    const embeds = images.map(f => `![[${f}]]`).join('\n');
    const original = esc(p.body_clean).split('\n').map(l => `> ${l}`).join('\n');
    return join(embeds, `**Originaltext:**\n\n${original}`);
  }
  return null; // unbekannt -> Template-Zeilen übernehmen bzw. leer
}
// Vorgegebene "- **Label:** wert"-Zeilen im Template befüllen
function fillLabelLines(tplLines, values) {
  return tplLines.map(l => {
    const m = l.match(/^(\s*-\s*\*\*([^*]+?):\*\*)\s*(.*)$/);
    if (!m) return null;
    const key = norm(m[2]);
    const v = values[key];
    return (v != null ? `${m[1]} ${v}` : `${m[1]} ${m[3]}`).replace(/\s+$/, '');
  }).filter(l => l != null).join('\n');
}

function render(p, a, ticker, prev, next, images) {
  const date = p.published_date;
  const statusName = ticker ? `${ticker} - Aktueller Stand` : '';
  const known = {
    typ: 'analysten-update', status: 'review', quelle: 'Patreon', analyst: 'The Long Investor',
    veroffentlicht: date, instrument: '', ticker: ticker || '', isin: '',
    zeithorizont: q(a.time_horizon), quell_url: q(p.post_url),
    vorganger: prev ? q(wl(prev)) : '""', vorgaenger: prev ? q(wl(prev)) : '""', nachfolger: next ? q(wl(next)) : '""',
  };
  const fm = ['---'];
  for (const k of TPL.fmKeys) {
    const n = norm(k).replace(/ /g, '_');
    if (n === 'analyseart') {
      const arten = (a.analysis_types || []).filter(x => ['technisch', 'fundamental'].includes(x));
      fm.push(`${k}:` + (arten.length ? '\n' + arten.map(x => `  - ${x}`).join('\n') : ' []'));
    } else fm.push(`${k}: ${known[n] != null ? known[n] : ''}`.replace(/\s+$/, ''));
  }
  // technische Zusatzfelder (für Dubletten, Status-Flow, Nachvollziehbarkeit)
  fm.push(
    'hauptkategorie: Technisch',
    'kategorie: "1 Analyse"',
    `einordnung_regel: ${q(p.regel)}`,
    `datum_status: ${p.date_status}`,
    `gmail_message_id: ${q(p.gmail_message_id)}`,
    `erwaehnte_ticker:${(a.mentioned_tickers || []).length ? '\n' + a.mentioned_tickers.map(x => `  - ${q(x)}`).join('\n') : ' []'}`,
    `konzepte:${(p.concept_links || []).length ? '\n' + p.concept_links.map(c => `  - ${q(c.begriff)}`).join('\n') : ' []'}`,
    `pruefhinweise:${(p.warnings || []).length ? '\n' + p.warnings.map(w => `  - ${q(w)}`).join('\n') : ' []'}`,
    `importiert_am: ${new Date().toISOString()}`,
    'verarbeitung:',
    `  workflow: ${q(WORKFLOW)}`,
    `  prompt_version: ${q(p.prompt_version)}`,
    `  modell: ${q(p.model)}`,
    `  kosten_cent: ${p.usage ? p.usage.cost_cent : 0}`,
    '---', '');

  const out = [fm.join('\n')];
  const ctx = { p, a, ticker, images };
  for (const b of TPL.blocks) {
    if (b.level === 1) {
      out.push('# ' + b.title.replace(/\{\{\s*date\s*\}\}/g, date).replace(/\[Instrument\]|\{\{\s*instrument\s*\}\}/gi, ticker || 'Allgemein'), '');
      continue;
    }
    out.push(`${'#'.repeat(b.level)} ${b.title}`);
    const t = norm(b.title);
    let content;
    if (t === 'quellenangabe') content = fillLabelLines(b.lines, {
      plattform: 'Patreon', analyst: 'The Long Investor', veroffentlichungsdatum: date,
      originalbeitrag: p.post_url || '', importart: p.is_forwarded ? 'E-Mail (weitergeleitet), Gmail-Automation' : 'E-Mail, Gmail-Automation',
    });
    else if (t === 'verknupfungen') content = fillLabelLines(b.lines, { wertpapierverlauf: statusName ? wl(statusName) : '' });
    else {
      content = sectionContent(b.title, ctx);
      if (content == null) content = b.lines.filter(l => !/\[\[[^\]]*\]\]/.test(l)).join('\n'); // unbekannter Abschnitt: Template-Text ohne Platzhalter-Links
    }
    out.push(content ? content + '\n' : '');
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n';
}

// Frontmatter-Feld setzen (vorhandene Schreibweise bevorzugen, sonst einfügen)
function setFm(text, keys, value) {
  const m = text.match(/^---\s*\n([\s\S]*?)\n---/);
  if (!m) return text;
  let fm = m[1];
  const key = keys.find(k => new RegExp(`^${k}:`, 'm').test(fm)) || keys[0];
  const re = new RegExp(`^${key}:.*$`, 'm');
  fm = re.test(fm) ? fm.replace(re, `${key}: ${value}`) : `${fm}\n${key}: ${value}`;
  return text.replace(m[0], `---\n${fm}\n---`);
}

// ---------- Platzhalter für Kategorien ohne eigene Auswertung (v1.0) ----------
const ABLAGE = {
  2: { ordner: t => `${ROOT}/${t}/2 Earnings`, template: 'Analysten-Earnings', wort: 'Earnings' },
  3: { ordner: t => `${ROOT}/${t}/3 Bewertung`, template: 'Analysten-Bewertung', wort: 'Bewertung' },
  4: { ordner: t => `${ROOT}/${t}/4 Grafiken & Kalender`, template: 'Analysten-Grafik-Kalender', wort: 'Grafik' },
  5: { ordner: () => `${ROOT}/5 Markt & Makro`, template: 'Analysten-Markt-Makro', wort: 'Makro' },
  6: { ordner: () => `${ROOT}/6 Newsletter`, template: 'Analysten-Newsletter', wort: 'Newsletter' },
  8: { ordner: () => `${ROOT}/8 Sonstige`, template: 'Analysten-Sonstige', wort: 'Sonstige' },
  9: { ordner: () => `${ROOT}/9 Manuelle Prüfung`, template: 'Analysten-Sonstige', wort: 'Prüfung' },
};

function parseFm(t) {
  const m = String(t).replace(/\r/g, '').match(/^---\s*\n([\s\S]*?)\n---/);
  const out = [];
  if (!m) return out;
  for (const l of m[1].split('\n')) {
    const k = l.match(/^([^\s:#-][^:]*):\s*(.*?)\s*$/);
    if (k) out.push({ key: k[1].trim(), value: k[2] });
  }
  return out;
}
function isoWoche(d) {
  const dt = new Date(d + 'T12:00:00Z');
  if (isNaN(dt)) return '';
  const day = (dt.getUTCDay() + 6) % 7;
  dt.setUTCDate(dt.getUTCDate() - day + 3);
  const first = new Date(Date.UTC(dt.getUTCFullYear(), 0, 4));
  return String(1 + Math.round(((dt - first) / 864e5 - 3 + ((first.getUTCDay() + 6) % 7)) / 7));
}

function renderPlatzhalter(p, ticker, images, tplName, linkStatus) {
  const tpl = TEMPLATES[tplName];
  if (!tpl) throw new Error(`Template Trading/Templates/${tplName}.md nicht gefunden`);
  const T = parseTemplate(tpl);
  const fmT = parseFm(tpl);
  const date = p.published_date;
  const nr = p.kategorie_nr;
  const titel = p.titel || p.subject || '';
  const quartal = (titel.match(/\bQ[1-4]\s*'?\s*\d{2,4}\b/i) || [''])[0];
  const known = {
    status: 'review', analyst: 'The Long Investor', veroffentlicht: date, instrument: ticker ? q(ticker) : '',
    ticker: ticker || '', quell_url: q(p.post_url), thema: nr >= 5 ? q(titel) : '', quartal: quartal ? q(quartal) : '',
  };
  if (nr === 9) { known.typ = 'analysten-pruefung'; known.kategorie = '9 Manuelle Prüfung'; }
  const fm = ['---'];
  for (const { key, value } of fmT) {
    const n = norm(key).replace(/ /g, '_');
    let v = known[n];
    if (v == null) v = ['typ', 'quelle', 'kategorie'].includes(n) ? value : '';   // feste Werte aus dem Template
    fm.push(`${key}: ${v}`.replace(/\s+$/, ''));
  }
  fm.push(
    `betreff: ${q(p.subject)}`,
    `einordnung_regel: ${q(p.regel)}`,
    ...(p.einordnung_grund ? [`einordnung_grund: ${q(p.einordnung_grund)}`] : []),
    `datum_status: ${p.date_status}`,
    `gmail_message_id: ${q(p.gmail_message_id)}`,
    `pruefhinweise:${(p.warnings || []).length ? '\n' + p.warnings.map(w => `  - ${q(w)}`).join('\n') : ' []'}`,
    'platzhalter: true',
    `importiert_am: ${new Date().toISOString()}`,
    'verarbeitung:',
    `  workflow: ${q(WORKFLOW)}`,
    '---', '');

  const hatAbbildungAbschnitt = T.blocks.some(b => norm(b.title) === 'abbildung');
  const hatOriginalinhalt = T.blocks.some(b => norm(b.title) === 'originalinhalt');
  const embeds = images.map(f => `![[${f}]]`).join('\n');
  const original = join(p.body_clean ? `**Originaltext:**\n\n${esc(p.body_clean).split('\n').map(l => `> ${l}`).join('\n')}` : '', pdfBlock(p));
  const hinweis = nr === 9
    ? `> [!warning] Manuelle Prüfung\n> ${esc(p.einordnung_grund || 'Beitrag konnte nicht eindeutig eingeordnet werden')}.\n> Betreff: ${esc(p.subject)}\n> Bitte einordnen und in den passenden Ordner verschieben.`
    : `> [!info] Platzhalter – Kategorie ${nr} ${esc(p.kategorie)}\n> Für diese Kategorie gibt es noch keine automatische Auswertung. Originaltext und Abbildungen stehen unten.\n> Betreff: ${esc(p.subject)}`;
  // Pfad-Notiz: welcher Pfad im Flow gegangen wurde und was dort später passiert (kommt aus dem Platzhalter-Node)
  const pf = p.pfad || {};
  const tk = s => esc(String(s || '').replace(/<TICKER>/g, ticker || 'TICKER'));
  const geplant = (pf.spaeter || []).map((x, i) => `> ${i + 1}. ${tk(x)}`).join('\n');
  const pfadNotiz = pf.kategorie
    ? `\n>\n> **Pfad im Flow:** ${esc(pf.kategorie)} → ${tk(pf.ziel)}` + (geplant ? `\n> **Später geplant:**\n${geplant}` : '')
    : '';

  const out = [fm.join('\n')];
  for (const b of T.blocks) {
    if (b.level === 1) {
      const art = /calendar|kalender/i.test(titel) ? 'Earnings-Kalender' : 'Infografik';
      const h1 = b.title
        .replace(/\{\{\s*date\s*\}\}/g, date)
        .replace(/\[Instrument oder Thema\]|\[Instrument\]|\{\{\s*instrument\s*\}\}/gi, ticker || titel)
        .replace(/\[Infografik \/ Earnings-Kalender\]/g, art)
        .replace(/\[Quartal\]/g, quartal)
        .replace(/\[Thema\]|\[Titel\]|\[Ausgabe\]/g, titel)
        .replace(/KW \[Nummer\]/g, `KW ${isoWoche(date)}`)
        .replace(/^Sonstige/, nr === 9 ? 'Manuelle Prüfung' : 'Sonstige')
        .replace(/ – Sonstige – /, nr === 9 ? ' – Manuelle Prüfung – ' : ' – Sonstige – ')
        .replace(/\s+–\s*$/, '').replace(/\s{2,}/g, ' ').trim();
      out.push('# ' + h1, '', hinweis + pfadNotiz, '');
      continue;
    }
    out.push(`${'#'.repeat(b.level)} ${b.title}`);
    const t = norm(b.title);
    let content;
    if (t === 'quellenangabe') content = fillLabelLines(b.lines, {
      plattform: 'Patreon', analyst: 'The Long Investor', veroffentlichungsdatum: date,
      originalbeitrag: p.post_url || '', importart: p.is_forwarded ? 'E-Mail (weitergeleitet), Gmail-Automation' : 'E-Mail, Gmail-Automation',
    });
    else if (t === 'verknupfungen') content = fillLabelLines(b.lines, {
      wertpapier: '', 'aktueller technischer stand': linkStatus ? wl(`${ticker} - Aktueller Stand`) : '',
    });
    else if (t === 'abbildung') content = embeds;
    else if (t === 'originalinhalt') content = original;
    else if (t.startsWith('originalabbildungen')) content = join(hatAbbildungAbschnitt ? '' : embeds, hatOriginalinhalt ? '' : original);
    else content = b.lines.filter(l => !/\[\[[^\]]*\]\]/.test(l)).join('\n'); // Template-Gerüst (Tabellen, Listen) leer übernehmen
    out.push(content ? content + '\n' : '');
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n';
}

