    ? [kopf, '|' + kopf.split('|').slice(1, -1).map(() => '---').join('|') + '|', ...zeilen].join('\n') : '';
  const kennzahlZeilen = list => list.map(z => `| ${zelle(z.kennzahl)} | ${zelle(z.wert)} | ${zelle(z.qoq)} | ${zelle(z.yoy)} | ${zelle(z.anmerkung)} |`);
  const KOPF5 = '| Kennzahl | Wert | QoQ | YoY | Anmerkung |';
