    if (t === 'zusammenfassung') content = esc(e.zusammenfassung);
    else if (t.startsWith('ergebnis gegenuber')) content = tabelle('| Kennzahl | Ist | Erwartung | Abweichung | Ergebnis |', [kopfZeile('Umsatz', e.umsatz), kopfZeile('EPS', e.eps)]);
    else if (t === 'umsatz') content = tabelle(KOPF5, kennzahlZeilen(e.umsatz_zeilen));
    else if (t.startsWith('operative')) content = tabelle(KOPF5, kennzahlZeilen(e.operative_zeilen));
    else if (t.startsWith('profitabilitat')) content = tabelle(KOPF5, kennzahlZeilen(e.profit_zeilen));
    else if (t.startsWith('ausblick')) content = e.guidance.status === 'keine' && !e.guidance.text ? 'Keine Prognose genannt.' : `**${esc(e.guidance.status)}**${e.guidance.text ? ' – ' + esc(e.guidance.text) : ''}`;
    else if (t.startsWith('kommentar')) content = bullets(e.kommentar);
