  const nr = p.kategorie_nr;
  const basis = { gmail_message_id: p.gmail_message_id, subject: p.subject, kategorie_nr: nr, kategorie: p.kategorie, regel: p.regel };
  if (nr === 0 || nr === 7) { mails.push({ ...basis, action: 'ignoriert', info: nr === 7 ? 'Video – wird derzeit nicht verarbeitet' : p.einordnung_grund }); continue; }
  if (!p.ok) { mails.push({ ...basis, action: 'fehler', info: (p.errors || []).join('; ') }); continue; }
  const dup = files.find(e => e.gmail_message_id && e.gmail_message_id === p.gmail_message_id);
  if (dup) { mails.push({ ...basis, action: 'dublette', info: dup.file_name }); continue; }

  let ticker = safe(p.ticker_hint || a.ticker).toUpperCase();
  let dir, base, content;
  const imgNames = [];
  const bildNamen = stamm => (p.images || []).map((url, i) => {
    const ext = ((url.split('?')[0].match(/\.(png|jpe?g|gif|webp)$/i) || [])[1] || 'png').toLowerCase();
    const fileName = `${stamm} - Abbildung ${i + 1}.${ext}`;
    bilder.push({ kind: 'bild', url, file_name: fileName, target_path: `${MEDIA}/${fileName}`, gmail_message_id: p.gmail_message_id });
    return fileName;
  });
  let prev = null, next = null;

  if (nr === 1) {
    // ---- Analyse: Inhalt von Claude, Template Analysten-Update ----
    if (!ticker) { mails.push({ ...basis, action: 'fehler', info: 'Analyse ohne Ticker' }); continue; }
    dir = `${ROOT}/${ticker}/1 technische Analyse/Updates`;
    base = `${safe(p.published_date)} - ${ticker} - Analysten-Update`;
    if (files.some(e => e.name === base)) base += ` - ${safe(p.gmail_message_id).slice(-6)}`;
    imgNames.push(...bildNamen(base.replace(' - Analysten-Update', '')));
    const chain = files
      .filter(e => istAnalyseUpdate(e) && e.ticker === ticker && e.date && /^\d{4}-\d{2}-\d{2}$/.test(e.date))
      .sort((x, y) => (x.date + x.name).localeCompare(y.date + y.name));
    const key = p.published_date + base;
    prev = chain.filter(e => (e.date + e.name) < key).pop() || null;
    next = chain.find(e => (e.date + e.name) > key) || null;
    content = render(p, a, ticker, prev && prev.name, next && next.name, imgNames);
  } else {
    // ---- Platzhalter nach Kategorie-Template ----
    const abl = ABLAGE[nr];
    if (!abl) { mails.push({ ...basis, action: 'fehler', info: `Keine Ablage für Kategorie ${nr}` }); continue; }
    if (nr >= 5) ticker = '';
    dir = abl.ordner(ticker);
    const kurz = safe(p.titel || p.subject).replace(/\s+/g, ' ').slice(0, 60).trim() || 'ohne Titel';
    base = ticker ? `${safe(p.published_date)} - ${ticker} - ${abl.wort}` : `${safe(p.published_date)} - ${abl.wort} - ${kurz}`;
    if (files.some(e => e.name === base)) base += ` - ${safe(p.gmail_message_id).slice(-6)}`;
    imgNames.push(...bildNamen(base));
    if (nr === 3 && p.pdf_datei) imgNames.push(p.pdf_datei); // PDF liegt schon in Media (Pfad "3 Bewertung")
    const linkStatus = !!ticker && files.some(e => istAnalyseUpdate(e) && e.ticker === ticker);
    if (nr === 3 && p.bewertung) {
      // ---- Bewertung: Inhalt von Claude aus dem PDF-Text, Reihenfolge der Bewertungen je Ticker ----
      const chain = files
        .filter(e => e.directory === dir && e.date && /^\d{4}-\d{2}-\d{2}$/.test(e.date))
        .sort((x, y) => (x.date + x.name).localeCompare(y.date + y.name));
      const key = p.published_date + base;
      prev = chain.filter(e => (e.date + e.name) < key).pop() || null;
      next = chain.find(e => (e.date + e.name) > key) || null;
      const eDir = `${ROOT}/${ticker}/2 Earnings`;
      const letzteEarnings = files.filter(e => e.directory === eDir && e.date && e.date <= p.published_date)
        .sort((x, y) => (x.date + x.name).localeCompare(y.date + y.name)).pop();
      content = renderBewertung(p, ticker, imgNames, linkStatus, prev && prev.name, next && next.name, letzteEarnings && letzteEarnings.name);
    } else if (nr === 2 && p.earnings) {
      // ---- Earnings: Inhalt von Claude (Grafik + Text), Reihenfolge der Quartale je Ticker ----
      const chain = files
        .filter(e => e.directory === dir && e.date && /^\d{4}-\d{2}-\d{2}$/.test(e.date))
        .sort((x, y) => (x.date + x.name).localeCompare(y.date + y.name));
      const key = p.published_date + base;
      prev = chain.filter(e => (e.date + e.name) < key).pop() || null;
      next = chain.find(e => (e.date + e.name) > key) || null;
      content = renderEarnings(p, ticker, imgNames, linkStatus, prev && prev.name, next && next.name);
    } else {
      content = renderPlatzhalter(p, ticker, imgNames, abl.template, linkStatus);
    }
  }

  const path = `${dir}/${base}.md`;
  if (!path.startsWith(ROOT + '/') || path.includes('..')) throw new Error('Unzulässiger Zielpfad: ' + path);
  files.push({ name: base, file_name: base + '.md', directory: dir, path, ticker, date: p.published_date, gmail_message_id: p.gmail_message_id, content, changed: true, isNew: true });

  if (prev) { prev.content = setFm(prev.content, [KEY_NACH, 'nachfolger'], q(wl(base))); prev.changed = true; }
  if (next) { next.content = setFm(next.content, [KEY_VOR, 'vorgänger', 'vorgaenger'], q(wl(base))); next.changed = true; }

  mails.push({
    ...basis, action: 'schreiben', info: base + '.md', ordner: dir.slice(ROOT.length + 1),
    ticker, datum: p.published_date, vorgaenger: prev ? prev.name : '', nachfolger: next ? next.name : '',
    abbildungen: imgNames.length, kosten_cent: p.usage ? p.usage.cost_cent : 0, warnungen: (p.warnings || []).length,
  });
}

// ---------- Ordnerstruktur je Wertpapier ----------
// Egal mit welcher Kategorie ein Ticker zum ersten Mal auftaucht (Analyse, Earnings, Bewertung, Grafik):
// es wird immer die komplette Struktur <TICKER>/{1 technische Analyse/{Aktueller Stand,Updates}, 2 Earnings,
// 3 Bewertung, 4 Grafiken & Kalender} angelegt. Vorhandene Ordner bleiben unverändert (mkdir -p).
// Leere Ordner bekommen eine .gitkeep, damit sie auch im Git-Repo sichtbar sind.
const TICKER_ORDNER = ['1 technische Analyse/Aktueller Stand', '1 technische Analyse/Updates', '2 Earnings', '3 Bewertung', '4 Grafiken & Kalender'];
function ordnerFuer(dir) {
  const top = dir.slice(ROOT.length + 1).split('/')[0];
  if (!top || /^\d /.test(top)) return [dir];                     // Kategorie-Ordner ohne Ticker (5, 6, 8, 9)
  return [...new Set([dir, ...TICKER_ORDNER.map(o => `${ROOT}/${top}/${o}`)])];
}
function mkdirBefehl(dirs) {
  for (const d of dirs) {
    if (!d.startsWith(ROOT + '/') || d.includes('..') || /["$`\\]/.test(d)) throw new Error('Unzulässiger Ordner: ' + d);
  }
  const quoted = dirs.map(d => `"${d}"`).join(' ');
  return `mkdir -p ${quoted} && for d in ${quoted}; do [ -n "$(ls -A "$d")" ] || touch "$d/.gitkeep"; done`;
}

const out = [];
for (const f of files.filter(f => f.changed)) {
  const path = f.path || '';
  if (!path.startsWith(ROOT + '/') || path.includes('..')) throw new Error('Unzulässiger Pfad beim Schreiben: ' + path);
  const dir = path.slice(0, path.lastIndexOf('/'));
  const ordner = ordnerFuer(dir);
  out.push({ json: {
    kind: 'datei', art: f.isNew ? 'neu' : 'reihenfolge_korrigiert',
    target_dir: dir, target_path: path, file_name: f.file_name,
    ordner_anlegen: ordner, befehl: mkdirBefehl(ordner),
    content_b64: Buffer.from(f.content, 'utf8').toString('base64'),
  } });
}
for (const b of bilder) out.push({ json: b });
for (const m of mails) out.push({ json: { kind: 'mail', ...m } });
return out;
